/** Version 1: state transitions and exponential pose blending; no game or asset defaults. */
export class AnimationStateMachine{
 constructor({initial='idle',states={},onTransition=()=>{}}={}){this.state=initial;this.states=states;this.elapsed=0;this.onTransition=onTransition;}
 set(next){if(!this.states[next]&&Object.keys(this.states).length)throw Error('Unknown animation state: '+next);if(next===this.state)return false;const old=this.state;this.states[old]?.exit?.(this);this.state=next;this.elapsed=0;this.states[next]?.enter?.(this);this.onTransition(next,old);return true;}
 update(dt,context){if(dt<=0)return;this.elapsed+=dt;this.states[this.state]?.update?.(dt,context,this);const d=this.states[this.state];if(d?.duration&&this.elapsed>=d.duration&&d.next)this.set(d.next);}
}
export const blendFactor=(dt,responsiveness=12)=>1-Math.exp(-Math.max(0,dt)*responsiveness);
export function blendJointPose(B,nodes,targets,rest,dt,{responsiveness=12}={}){const f=blendFactor(dt,responsiveness);for(const[name,node]of Object.entries(nodes)){const t=targets[name]||{},position=t.position||rest[name]?.position,rotation=t.rotation||[0,0,0];if(position)node.position=B.Vector3.Lerp(node.position,new B.Vector3(...position),t.immediate?1:f);const q=(Array.isArray(t.quaternion)?B.Quaternion.FromArray(t.quaternion):t.quaternion)||B.Quaternion.FromEulerAngles(...rotation);node.rotationQuaternion=B.Quaternion.Slerp(node.rotationQuaternion||B.Quaternion.Identity(),q,t.immediate?1:f);}}
/** Smoothly weights imported clips. Caller supplies state->clip names and speed. */
export function createClipMixer(groups,mapping={idle:'Idle',walk:'Walk'}){let current=null;const weights=new Map(),sampled=new Set();for(const g of groups){g.stop();g.enableBlending=true;}return{set(state,speed=1){const name=mapping[state]||mapping.idle,target=groups.find(g=>g.name===name||g.name.endsWith(':'+name));if(target!==current){current=target;if(target&&!target.isStarted)target.start(true,1); }if(target)target.speedRatio=speed;},update(dt){for(const g of groups){const w=(weights.get(g)||0)+((g===current?1:0)-(weights.get(g)||0))*blendFactor(dt,10);weights.set(g,w);g.setWeightForAllAnimatables(w);if(g!==current&&w<.005&&g.isStarted)g.stop();}},sample(progress,{exclusive=false}={}){if(!current)return;if(!Number.isFinite(progress)){if(sampled.has(current)){current.stop();current.enableBlending=true;current.start(true,1);sampled.delete(current);}return;}if(!sampled.has(current)){current.stop();current.enableBlending=false;current.start(true,1);sampled.add(current);}current.pause();if(exclusive)for(const g of groups){const w=g===current?1:0;weights.set(g,w);g.setWeightForAllAnimatables(w);if(g!==current&&g.isStarted)g.stop();}current.goToFrame(current.from+(current.to-current.from)*Math.max(0,Math.min(1,progress)));},dispose(){groups.forEach(g=>g.stop());sampled.clear();}};}
